`timescale 1ns/1ps
// Public application/configuration/GMII pins only. Files are generated by fragment_integration.py.
module tb_fragmentation #(parameter integer PAYLOAD_CAPACITY=65536);
reg clk=0; always #4 clk=~clk;
reg reset=1;
integer cycle=0, errors=0, done=0;
reg [7:0] input_data=0; reg input_valid=0;
wire input_ready; wire [7:0] output_data; wire output_valid;
wire [7:0] a,b; wire av,bv;
reg inject_mode=0, inj_av=0,inj_bv=0; reg [7:0] inj_a=0,inj_b=0;
reg c1wr=0,c2wr=0;reg [17:0] c1addr=0,c2addr=0;reg [31:0] c1data=0,c2data=0;
wire c1ready,c2ready; wire [2:0] app1,app2; wire [6:0] evt1,evt2;
wire [7:0] eva1,evb1,eva2,evb2; wire rm1,rm2,del1,del2;
AFDX_top tx(.clk(clk),.reset(reset),.tx_data(input_data),.tx_valid(input_valid),.tx_ready(input_ready),
 .rx_data(),.rx_valid(),.rx_ready(1'b1),.gmii_txd_a(a),.gmii_tx_en_a(av),.gmii_txd_b(b),.gmii_tx_en_b(bv),
 .gmii_rxd_a(8'b0),.gmii_rx_dv_a(1'b0),.gmii_rxd_b(8'b0),.gmii_rx_dv_b(1'b0),
 .cfg_wr(c1wr),.cfg_rd(1'b0),.cfg_addr(c1addr),.cfg_wdata(c1data),.cfg_rdata(),.cfg_rvalid(),.cfg_ready(c1ready),
 .ev_tx(evt1),.ev_a(eva1),.ev_b(evb1),.ev_rm_drop(rm1),.ev_deliver(del1),.ev_app(app1));
AFDX_top rx(.clk(clk),.reset(reset),.tx_data(8'b0),.tx_valid(1'b0),.tx_ready(),
 .rx_data(output_data),.rx_valid(output_valid),.rx_ready(1'b1),.gmii_txd_a(),.gmii_tx_en_a(),.gmii_txd_b(),.gmii_tx_en_b(),
 .gmii_rxd_a(inject_mode?inj_a:a),.gmii_rx_dv_a(inject_mode?inj_av:av),
 .gmii_rxd_b(inject_mode?inj_b:b),.gmii_rx_dv_b(inject_mode?inj_bv:bv),
 .cfg_wr(c2wr),.cfg_rd(1'b0),.cfg_addr(c2addr),.cfg_wdata(c2data),.cfg_rdata(),.cfg_rvalid(),.cfg_ready(c2ready),
 .ev_tx(evt2),.ev_a(eva2),.ev_b(evb2),.ev_rm_drop(rm2),.ev_deliver(del2),.ev_app(app2));
reg [7:0] payload[0:PAYLOAD_CAPACITY-1]; reg [7:0] injection[0:262143];
integer config_file,schedule_file,inj_file,fd_a,fd_b,fd_rx,fd_tx,fd_ev,rc;
integer configs,idx,vl,bag,lmax,sport,dport,n,off,due,msgs,k,j,epoch,start,net,wait_cycles,flen,foff,ni;
integer deliveries=0,target=0,deadline,drop_long=0,drop_app=0;
reg prev_rx=0,prev_a=0,prev_b=0;
reg [7:0] rb[0:8193],ab[0:2047],bb[0:2047]; integer rn=0,an=0,bn=0,rs=0,as_=0,bs=0;
integer inj_count,payload_count;
always @(posedge clk) begin
 cycle=cycle+1;
 if (!reset) begin
  if(evt1[3]) drop_long=drop_long+1;
  if(app1[1]) drop_app=drop_app+1;
  if(output_valid) begin if(!prev_rx)begin rn=0;rs=cycle;end if(rn<8194)rb[rn]=output_data;rn=rn+1;end
  else if(prev_rx)begin
   if(rn>8194)begin $display("[FAIL] receive overflow");errors=errors+1;end
   $fwrite(fd_rx,"%0d %0d %02x%02x ",rs,cycle-1,rb[0],rb[1]);for(j=2;j<rn && j<8194;j=j+1)$fwrite(fd_rx,"%02x",rb[j]);$fwrite(fd_rx,"\n");$fflush(fd_rx); deliveries=deliveries+1;
  end
  prev_rx=output_valid;
  if(av)begin if(!prev_a)begin an=0;as_=cycle;end if(an<2048)ab[an]=a;an=an+1;end
  else if(prev_a)begin $fwrite(fd_a,"%0d ",as_);for(j=0;j<an && j<2048;j=j+1)$fwrite(fd_a,"%02x",ab[j]);$fwrite(fd_a,"\n");$fflush(fd_a);if(an>2048)errors=errors+1;end
  prev_a=av;
  if(bv)begin if(!prev_b)begin bn=0;bs=cycle;end if(bn<2048)bb[bn]=b;bn=bn+1;end
  else if(prev_b)begin $fwrite(fd_b,"%0d ",bs);for(j=0;j<bn && j<2048;j=j+1)$fwrite(fd_b,"%02x",bb[j]);$fwrite(fd_b,"\n");$fflush(fd_b);if(bn>2048)errors=errors+1;end
  prev_b=bv;
  if(app1 || evt1[4:1] || eva2[7:1] || evb2[7:1] || rm2) $fwrite(fd_ev,"%0d %02x %02x %02x %02x %01x\n",cycle,evt1,eva2,evb2,app1,rm2);
 end
end
task cfg1;input [17:0] addr; input [31:0] data;begin
 @(negedge clk);while(!c1ready)@(negedge clk);c1addr=addr;c1data=data;c1wr=1;@(negedge clk);c1wr=0;while(!c1ready)@(negedge clk);
end endtask
task cfg2;input [17:0] addr; input [31:0] data;begin
 @(negedge clk);while(!c2ready)@(negedge clk);c2addr=addr;c2data=data;c2wr=1;@(negedge clk);c2wr=0;while(!c2ready)@(negedge clk);
end endtask
task send;input integer id,len,offset;integer p;begin
 while(!input_ready)@(negedge clk);
 @(negedge clk);start=cycle+1;input_valid=1;input_data=id>>8;
 @(negedge clk);input_data=id;
 for(p=0;p<len;p=p+1)begin @(negedge clk);input_data=payload[offset+p];end
 @(negedge clk);input_valid=0;$fwrite(fd_tx,"%0d %0d %0d %0d\n",start,cycle,id,len);$fflush(fd_tx);
end endtask
initial begin
 fd_a=$fopen("tx_a.txt","w");fd_b=$fopen("tx_b.txt","w");fd_rx=$fopen("rx.txt","w");fd_tx=$fopen("tx_messages.txt","w");fd_ev=$fopen("events.txt","w");
 config_file=$fopen("vectors/config.txt","r");schedule_file=$fopen("vectors/schedule.txt","r");inj_file=$fopen("vectors/injection.txt","r");
 if(!fd_a||!fd_b||!fd_rx||!fd_tx||!fd_ev||!config_file||!schedule_file||!inj_file)begin $display("[RESULT] tb_fragmentation FAIL file");$finish;end
 rc=$fscanf(config_file,"%d",configs);
 rc=$fscanf(schedule_file,"%d %d %d",msgs,payload_count,target);
 if(msgs<1 || payload_count<1 || payload_count>PAYLOAD_CAPACITY)begin
  $display("[RESULT] tb_fragmentation FAIL schedule payload_count=%0d capacity=%0d",payload_count,PAYLOAD_CAPACITY);$finish;
 end
 $readmemh("vectors/payload.hex",payload,0,payload_count-1);
 rc=$fscanf(inj_file,"%d %d",ni,inj_count);if(inj_count>0)$readmemh("vectors/injection.hex",injection,0,inj_count-1);
 repeat(8)@(negedge clk);reset=0;
 for(idx=0;idx<configs;idx=idx+1)begin
  rc=$fscanf(config_file,"%d %d %d %d %d",vl,bag,lmax,sport,dport);
  if(rc!=5)begin $display("[RESULT] tb_fragmentation FAIL config");$finish;end
  cfg1(18'h1000+idx*8,lmax*512+63*8+7);cfg1(18'h1001+idx*8,bag*125);cfg1(18'h1002+idx*8,vl);
  cfg1(18'h1003+idx*8,32'h0a000101+idx);cfg1(18'h1004+idx*8,32'he0e00000|vl);cfg1(18'h1005+idx*8,(sport<<16)|dport);
  cfg2(18'h10000+vl,4096+idx);cfg2(18'h20000+idx,lmax*131072+20*32+31);
 end
 epoch=cycle+16;$fwrite(fd_tx,"E %0d\n",epoch);
 for(idx=0;idx<msgs;idx=idx+1)begin
  rc=$fscanf(schedule_file,"%d %d %d %d",due,vl,n,off);
  if(rc!=4 || n<1 || n>8193 || off<0 || off+n>payload_count)begin $display("[RESULT] tb_fragmentation FAIL row");$finish;end
  while(cycle<epoch+due)@(negedge clk);send(vl,n,off);
 end
 deadline=cycle+2000000;
 while(deliveries<target && cycle<deadline)@(negedge clk);
 if(deliveries<target)begin $display("[RESULT] tb_fragmentation FAIL missing deliveries %0d/%0d",deliveries,target);$finish;end
 // Wait after the oversize request so late frames or partial delivery cannot escape the checker.
 repeat(2000)@(negedge clk);
 inject_mode=1;
 for(idx=0;idx<ni;idx=idx+1)begin
  rc=$fscanf(inj_file,"%d %d %d %d",net,foff,flen,wait_cycles);
  if(rc!=4 || flen<1 || foff+flen>inj_count)begin $display("[RESULT] tb_fragmentation FAIL injection row");$finish;end
  repeat(wait_cycles)@(negedge clk);
  for(k=0;k<flen;k=k+1)begin @(negedge clk);inj_av=(net==1);inj_bv=(net==2);inj_a=injection[foff+k];inj_b=injection[foff+k];end
  @(negedge clk);inj_av=0;inj_bv=0;
 end
 repeat(20000)@(negedge clk);
 $fwrite(fd_ev,"FINAL %0d %0d %0d\n",deliveries,drop_long,drop_app);$fflush(fd_ev);
 if(errors) $display("[RESULT] tb_fragmentation FAIL errors=%0d",errors);
 else $display("[RESULT] tb_fragmentation PASS errors=0 deliveries=%0d",deliveries);
 $finish;
end
endmodule
